import{_ as i,l,o as e,c as s,v as t,p as n,x as o,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"协程与生成器实现","description":"","frontmatter":{"title":"协程与生成器实现","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/coroutines-impl.md","filePath":"cs/coroutines-impl.md","lastUpdated":1789023840000}'),h={name:"cs/coroutines-impl.md"};function u(m,a,_,E,P,S){const r=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="协程与生成器实现" tabindex="-1">协程与生成器实现 <a class="header-anchor" href="#协程与生成器实现" aria-label="Permalink to &quot;协程与生成器实现&quot;">​</a></h1><div class="epigraph"><p>生成器是半协程：`yield` 保存 PC 与局部，下次从该点继续。实现或把状态机编到堆帧，或切换独立栈。</p><footer>—— 据 Moura and Ierusalimschy, Revisiting Coroutines；C# / Python 生成器实现；对照 CPS 整理</footer></div><p>上一课<a href="/cs/cps-continuations">CPS</a> 把控制变成函数。生成器不必全 CPS：编译器把函数切成状态机。缺口是<strong>暂停点的帧</strong>。蹦床下一课。不写异步 IO 框架百科。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>yield x</code> 返回值给调用者，但局部还要活。方案 A：变换成类，字段=局部，<code>switch(state)</code>。方案 B：独立栈，切换 SP。缺口是<strong>与 GC 根、展开表的关系</strong>，不是 call/cc 全权。</p><p>async/await 是生成器+将来值的语法，实现同类。</p><h3 id="生成器不是操作系统线程" tabindex="-1">生成器不是操作系统线程 <a class="header-anchor" href="#生成器不是操作系统线程" aria-label="Permalink to &quot;生成器不是操作系统线程&quot;">​</a></h3><p>用户态、协作式。不要和抢占线程混。切换代价应远小于 <code>pthread</code>。</p><p><span class="marginnote">Moura–Ierusalimschy。Python 的 frame 对象。LLVM 协程表示（CoroSplit）。本课两种实现对照。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>前端标暂停点。CoroSplit：把 SSA 跨 yield 的值溢到协程帧。调用：resume 恢复 PC。完成：销毁帧。</p>',11)),(e(),n(p,null,{default:o(()=>[c(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20YLD%5B%22yield%22%5D%20--%3E%20SAVE%5B%22%E4%BF%9D%E5%AD%98%20PC%20%E4%B8%8E%E6%B4%BB%E5%80%BC%22%5D%0A%20%20SAVE%20--%3E%20RET%5B%22%E8%BF%94%E5%9B%9E%E8%B0%83%E7%94%A8%E8%80%85%22%5D%0A%20%20RET%20--%3E%20RES%5B%22resume%20%E6%81%A2%E5%A4%8D%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与闭包：协程帧是环境的亲戚。与 DWARF：展开要认协程帧布局。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>栈满协程：每个对象一页栈，内存多。状态机：内存少，不能任意深度互递归 yield 除非堆分配。不要在持锁时 yield 而不文档。</p><p>异常：在 yield 对面抛，状态机要能传播。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写蹦床。后课默认：生成器=可暂停帧。下一课蹦床与尾递归：另一套无栈控制。</p><p>也不把协程当化学课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>生成器：状态机或独立栈保存暂停点。</li><li>与 CPS 同类控制，实现更特化。</li><li>GC、展开、锁是正确性边界。</li><li>出处：Moura and Ierusalimschy；语言实现（Python/C#）；LLVM CoroSplit。</li></ul>',9))])}const A=i(h,[["render",u]]);export{C as __pageData,A as default};
